def completar_servicios(apps, schema_editor):
    """Token de ingesta y slug únicos para los servicios que ya existían."""
    import secrets
    from django.utils.text import slugify

    Servicio = apps.get_model('dashboard', 'Servicio')
    usados = set()
    for s in Servicio.objects.all():
        if not s.ingest_token:
            s.ingest_token = secrets.token_urlsafe(32)
        if not s.slug:
            base = slugify(s.nombre)[:45] or f'servicio{s.pk}'
            slug, n = base, 2
            while slug in usados or Servicio.objects.filter(slug=slug).exclude(pk=s.pk).exists():
                slug, n = f'{base}-{n}', n + 1
            s.slug = slug
        usados.add(s.slug)
        s.save(update_fields=['ingest_token', 'slug'])

    # Grupo que habilita el panel de desarrolladores (/dev/)
    Group = apps.get_model('auth', 'Group')
    Group.objects.get_or_create(name='Desarrolladores')


